/// Returns flashcards for the active application locale.
pub fn review_cards(locale: Locale) -> &'static [ReviewCard] {
    match locale {
        Locale::vi => VIETNAMESE_CARDS,
        Locale::en => ENGLISH_CARDS,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn english_resource_contains_short_learning_cards() {
        let cards = review_cards(Locale::en);
        assert!(cards.len() > 67);
        assert_eq!(cards[0].id, "cv-1");
        assert!(!cards[0].simple_explanation.is_empty());
        assert!(cards.iter().any(|card| card.id.ends_with("-a")));
    }

    #[test]
    fn vietnamese_resource_contains_short_learning_cards() {
        let cards = review_cards(Locale::vi);
        assert!(cards.len() > 67);
        assert_eq!(cards[0].id, "cv-1");
        assert!(!cards[0].simple_explanation.is_empty());
        assert!(cards.iter().any(|card| card.id == "cv-1-a"));
    }
}
